import { activate_and_reactivate_designations } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(activate_and_reactivate_designations, {
          designation_id: this.rowInfo.designation_id,
          designation_status: "DEACTIVE"
        }));
        var response = JSON.parse(result.data.activate_and_reactivate_designations);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to delete designation");
        }
      } catch (error) {
        console.error("Error deleting designation:", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to delete designation. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.loading = false;
      }
    }
  }
};
